/**
 * User CRUD actions — modal create/edit, suspend/activate, delete.
 *
 * @module     local_airpay_users/user_actions
 * @copyright  2026 Airpay Payment Services
 * @license    http://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later
 */
define("local_airpay_users/user_actions", [
    "core_form/modalform",
    "core/str",
    "core/notification",
    "core/ajax"
], function(ModalForm, Str, Notification, Ajax) {
    "use strict";

    var openUserForm = function(userid, returnFocus) {
        var titleKey = (userid === 0) ? "adduser" : "edituser";
        Str.get_string(titleKey, "local_airpay_users").then(function(title) {
            var modalForm = new ModalForm({
                formClass: "local_airpay_users\\form\\edit_user",
                args: {userid: userid},
                modalConfig: {title: title},
                returnFocus: returnFocus
            });
            modalForm.addEventListener(modalForm.events.FORM_SUBMITTED, function(event) {
                var message = (event.detail && event.detail.message) || "Saved.";
                Notification.addNotification({message: message, type: "success"});
                window.location.reload();
            });
            modalForm.show();
            return null;
        }).catch(Notification.exception);
    };

    var confirmSuspend = function(userid, username, suspend, returnFocus) {
        var titleKey = suspend ? "suspenduser" : "activateuser";
        var msgKey = suspend ? "confirmsuspend" : "confirmactivate";
        var successKey = suspend ? "usersuspended" : "useractivated";
        Promise.all([
            Str.get_string(titleKey, "local_airpay_users"),
            Str.get_string(msgKey, "local_airpay_users", username),
            Str.get_string(successKey, "local_airpay_users")
        ]).then(function(strings) {
            var title = strings[0], message = strings[1], successMsg = strings[2];
            Notification.confirm(title, message, title, null, function() {
                Ajax.call([{
                    methodname: "local_airpay_users_suspend_user",
                    args: {userid: userid, suspended: suspend}
                }])[0].then(function() {
                    Notification.addNotification({message: successMsg, type: "success"});
                    window.location.reload();
                    return null;
                }).catch(Notification.exception);
            });
            if (returnFocus) {
                setTimeout(function() { returnFocus.focus(); }, 100);
            }
            return null;
        }).catch(Notification.exception);
    };

    var confirmDelete = function(userid, username, returnFocus) {
        Promise.all([
            Str.get_string("deleteuser", "local_airpay_users"),
            Str.get_string("confirmdelete", "local_airpay_users", username),
            Str.get_string("delete", "core"),
            Str.get_string("userdeleted", "local_airpay_users")
        ]).then(function(strings) {
            var title = strings[0], message = strings[1],
                deleteLabel = strings[2], successMsg = strings[3];
            Notification.deleteCancelPromise(title, message, deleteLabel, returnFocus)
                .then(function() {
                    Ajax.call([{
                        methodname: "local_airpay_users_delete_user",
                        args: {userid: userid}
                    }])[0].then(function() {
                        Notification.addNotification({message: successMsg, type: "success"});
                        window.location.reload();
                        return null;
                    }).catch(Notification.exception);
                    return true;
                }, function() { return null; });
            return null;
        }).catch(Notification.exception);
    };

    var handleClick = function(event) {
        var trigger = event.target.closest("[data-action]");
        if (!trigger) return;
        var action = trigger.dataset.action;
        var userid = parseInt(trigger.dataset.userid || "0", 10);
        var username = trigger.dataset.username || "this user";
        switch (action) {
            case "create-user":
                event.preventDefault();
                openUserForm(0, trigger);
                break;
            case "edit-user":
                event.preventDefault();
                openUserForm(userid, trigger);
                break;
            case "suspend-user":
                event.preventDefault();
                confirmSuspend(userid, username, true, trigger);
                break;
            case "activate-user":
                event.preventDefault();
                confirmSuspend(userid, username, false, trigger);
                break;
            case "delete-user":
                event.preventDefault();
                confirmDelete(userid, username, trigger);
                break;
        }
    };

    return {
        init: function() {
            var root = document.querySelector('[data-region="airpay-users"]') || document.body;
            if (root.dataset.airpayUsersInit === "1") return;
            root.dataset.airpayUsersInit = "1";
            root.addEventListener("click", handleClick);
        }
    };
});
